const learningPaths={solo:{name:'Solo path',ids:[0,1,2,5],description:'Your computer → your own GitHub repository. Learn one person’s workflow first.'},team:{name:'Team path',ids:[3,4],description:'Join an existing project → propose changes → review → resolve conflicts.'}};
