let lessonStarted=false;
let lesson=0,step=0,mode='solo',view='introduction',playing=false,timer=null,commandHistory=[],historyIndex=0;let completed=[];try{completed=JSON.parse(localStorage.getItem('git-orbit-completed')||'[]');if(!Array.isArray(completed))completed=[]}catch{}let state;
const classicRecipe=['# Pancake recipe','Flour: 1 cup','Milk: 1 cup','Sugar: 1 tablespoon','Chocolate chips: none','','Mix flour, milk, and sugar.','Cook until golden.'].join('\n');
