window.addEventListener('resize',()=>setWorkspacePane(workspacePane));
document.addEventListener('keydown',event=>{
  const button=event.target.closest('[data-workspace-pane],[data-guide-pane]');
  if(!button||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
  event.preventDefault();const selector=button.hasAttribute('data-workspace-pane')?'[data-workspace-pane]':'[data-guide-pane]';
  const buttons=[...button.parentElement.querySelectorAll(selector)].filter(b=>!b.hidden&&getComputedStyle(b).display!=='none');
  let index=buttons.indexOf(button);index=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;
  const next=buttons[index];if(selector==='[data-workspace-pane]')setWorkspacePane(next.dataset.workspacePane);else setGuidePane(next.dataset.guidePane);next.focus({preventScroll:true});
});
function resetLesson(){stopTour();workspacePane='file';guidePane='current';$('.lesson-context').open=false;$('#console-result').textContent='Run a step to see what changed.';$('.lesson-outline').open=true;step=0;resetLessonQuiz();state=initialState();if(lesson===4){state.feature='e9a2f5';state.main='d6c1b2';state.commits.push(makeCommit('d6c1b2','Your recipe: 1 tablespoon of sugar','a1c9e2','main'),makeCommit('e9a2f5','Maya’s recipe: 2 tablespoons of sugar','a1c9e2','feature','Maya'));state.remote=state.main;state.tracking=state.main}if(lesson===5){state.commits.push(makeCommit('d6c1b2','Accidentally remove flour','a1c9e2'));state.main=state.remote=state.tracking='d6c1b2'}if(lesson===4){state.commits.find(c=>c.id===state.feature).content=updateRecipeLine(classicRecipe,'Sugar:','Sugar: 2 tablespoons');}if(lesson===5){state.commits.find(c=>c.id===state.main).content=classicRecipe.split('\n').filter(line=>!line.startsWith('Flour:')).join('\n');}state.file=state.initialized?recipeAt(state[state.branch]):null;$('#terminal-output').innerHTML='<div class="terminal-welcome"><span>✦</span> A fresh sandbox. Try a quick command or follow the lesson.</div>';render();}
