function renderZones(){let zones=[['▱','Working directory',state.working?'pancakes.txt':null,state.main?'Tracked recipe · no edits':state.initialized?'No files yet':'Empty project folder'],['◫','Staging area',state.staged?'pancakes.txt':null,'Your next snapshot'],['⑂','Repository',state[state.branch],state.initialized?'No commits yet':'Run git init first']];if(lesson===3&&!state.initialized)zones=[['▱','Your computer',null,'No local copy yet'],['↓','Next action',null,'Clone the existing project'],['⑂','GitHub repository',state.remote,'Maya’s existing recipe']];if(lesson===4){zones[0][2]=state.working?'pancakes.txt':null;zones[1][2]=state.staged?'pancakes.txt':null}if(lesson===3&&state.pr)zones=[['♧','Pull request',`feature → main`,state.pr],['◫','Review',state.pr==='approved'||state.pr==='merged'?'Maya approved':null,'Waiting for Maya'],['⑂','GitHub main',state.remote,'Shared with your team']];$('#file-zones').innerHTML=zones.map((z,i)=>`<div class="file-zone ${z[2]?'active':''}"><div class="zone-title"><b>${z[0]}</b>${z[1]}<span class="zone-count">${i===2?state.commits.length:z[2]?1:0}</span></div><div class="${z[2]?'zone-file':'zone-empty'}">${z[2]||z[3]}${z[2]?'<em>'+ (i===2?'✓':i===1?'A':'M')+'</em>':''}</div></div>`).join('');const old=$('.conflict-editor');if(old)old.remove();if(lesson===4&&state.conflict){const e=document.createElement('div');e.className='conflict-editor';e.innerHTML=`<p>pancakes.txt · Choose the sugar amount, then stage the file.</p><pre>${state.resolved?`${state.resolution}`:'<<<<<<< HEAD\nSugar: 1 tablespoon\n=======\nSugar: 2 tablespoons\n>>>>>>> feature'}</pre><div class="conflict-options"><button data-resolve="Sugar: 1 tablespoon">Keep yours · 1 tablespoon</button><button data-resolve="Sugar: 2 tablespoons">Keep Maya’s · 2 tablespoons</button><button data-resolve="Sugar: 1.5 tablespoons">Agree on · 1.5 tablespoons</button></div>`;$('#file-zones').after(e)}}
function editedRecipe(){let content=state.file??classicRecipe;if(!state[state.branch]&&state.revision===1)return classicRecipe;if(state.branch==='feature'){const chips=content.includes('Chocolate chips: 2 tablespoons')?'Chocolate chips: 3 tablespoons':'Chocolate chips: 2 tablespoons';return updateRecipeLine(content,'Chocolate chips:',chips)}if(content.includes('Cook until golden.'))return updateRecipeLine(content,'Cook ','Cook on medium heat until golden.');if(content.includes('Milk: 1 cup'))return updateRecipeLine(content,'Milk:','Milk: 1.25 cups');return updateRecipeLine(content,'Cook ',content.includes('Cook for 2 minutes on each side.')?'Cook for 3 minutes on each side.':'Cook for 2 minutes on each side.')}
