function fileDifference(before,after){const a=(before??'').split('\n'),b=(after??'').split('\n');if(before===null)a.length=0;if(after===null)b.length=0;const table=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));for(let i=a.length-1;i>=0;i--)for(let j=b.length-1;j>=0;j--)table[i][j]=a[i]===b[j]?table[i+1][j+1]+1:Math.max(table[i+1][j],table[i][j+1]);let i=0,j=0,left=[],right=[];while(i<a.length||j<b.length){if(i<a.length&&j<b.length&&a[i]===b[j]){left.push({text:a[i],number:++i,kind:''});right.push({text:b[j],number:++j,kind:''})}else if(j<b.length&&(i===a.length||table[i][j+1]>=table[i+1][j])){right.push({text:b[j],number:++j,kind:'added'})}else{left.push({text:a[i],number:++i,kind:'removed'})}}return{left,right,added:right.filter(l=>l.kind).length,removed:left.filter(l=>l.kind).length}}
