function isAncestor(ancestor,descendant){if(ancestor===descendant)return true;const c=state.commits.find(c=>c.id===descendant);return!!c&&(Array.isArray(c.parent)?c.parent:[c.parent]).filter(Boolean).some(p=>isAncestor(ancestor,p))}
function performAction(){if(view==='lesson-intro'){beginLesson();return}if(step>=lessons[lesson].steps.length){if(recapState.finished)continueAfterLesson();else focusLessonQuiz();return}const action=lessons[lesson].steps[step][2];if(workspacePane!=='terminal'&&['remote-change','open-pr','review-pr','merge-pr'].includes(action))workspacePane=action==='remote-change'?'file':'graph';if(action.startsWith('git remote add origin ')&&state.remoteConfigured){log('origin is already connected from your earlier command. The connection step is complete; no files have been uploaded yet.','success');advance();return}if(action==='remote-change'){log('You: open pancakes.txt in GitHub’s editor and commit clearer mixing instructions.','command');state.commitContent=updateRecipeLine(recipeAt(state.remote),'Mix ','Whisk flour, milk, and sugar until smooth.');state.fileTab='github';state.fileNotice='You changed the mixing line online. Your computer’s recipe still has the old instruction.';addCommit('Clarify mixing instructions online','remote',state.remote,'You');log('GitHub has a new snapshot. Your local main has not changed.','success');advance();return}if(action==='open-pr'){state.pr='open';log('GitHub: opened pull request #1 · feature → main.','command');log('Maya can inspect the diff, discuss changes, and review the proposal.');advance();return}if(action==='review-pr'){state.pr='approved';state.commitContent=updateRecipeLine(recipeAt(state.remote),'Mix ','Whisk flour, milk, and sugar until smooth.');state.fileTab='github';state.fileNotice='Leo updated the mixing line on GitHub. Your local feature still contains your chocolate variation.';addCommit('Leo clarifies mixing instructions','remote',state.remote,'Leo');log('Leo pushed an independent update to GitHub main. Your feature keeps its own history.');log('Maya reviewed your diff and approved pull request #1.','success');advance();return}if(action==='merge-pr'){const id=addCommit('Merge pull request #1','remote',[state.remote,state.feature],'Maya');state.remote=id;state.pr='merged';state.branch='main';state.file=recipeAt(state.main);state.fileTab='github';state.fileNotice='GitHub’s merged recipe contains chocolate chips and clearer mixing instructions. Pull to update your computer.';log('GitHub created a merge commit. Your local main still needs to be updated.','success');advance();return}if(action==='team-pull'){execute('git pull --ff-only origin main');return}if(action==='resolve-conflict'){toast('Choose a sugar amount with the buttons at the bottom.');return}execute(action)}
function resolveConflict(value){if(workspacePane!=='terminal')workspacePane='file';state.resolved=true;state.resolution=value;state.working='resolved';state.file=updateRecipeLine(recipeAt(state.main),'Sugar:',value);state.fileTab='working';state.fileNotice='Conflict markers are gone. The recipe now contains your chosen sugar amount; stage it next.';log(`Resolved pancakes.txt: ${value}`,'success');if(step===1)advance();else render()}
function inspectCommit(id){const c=state.commits.find(c=>c.id===id);if(!c)return;openDialog(`<div class="detail-label">COMMIT SNAPSHOT</div><h2>${escapeHTML(c.message)}</h2><p><code>${c.id}</code> · ${c.author}</p><p>Parent${Array.isArray(c.parent)?'s':''}: <code>${Array.isArray(c.parent)?c.parent.join(' + '):c.parent||'None — the first commit'}</code></p><p>${Array.isArray(c.parent)?'This merge commit joins two lines of history.':'This snapshot belongs to the repository history. Branch labels can move; the saved snapshot stays the same.'}</p><div class="commit-file"><strong>pancakes.txt · saved in this commit</strong><pre>${escapeHTML(c.content)}</pre></div><p>Click another circle to inspect that version’s actual recipe.</p>`)}
function openDialog(html){$('#detail-content').innerHTML=html;$('#detail-dialog').showModal()}
function stopTour(){playing=false;clearTimeout(timer);if($('#tour'))$('#tour').innerHTML='<span>▷</span> Play walkthrough'}
function tickTour(){if(!playing)return;if(step>=lessons[lesson].steps.length){stopTour();return}if(lesson===4&&step===1)resolveConflict('Sugar: 1.5 tablespoons');else performAction();timer=setTimeout(tickTour,2400)}
function toggleTour(){if(playing){stopTour();return}if(step>=lessons[lesson].steps.length)resetLesson();playing=true;$('#tour').innerHTML='<span>Ⅱ</span> Pause walkthrough';tickTour()}
function renderView(){document.body.classList.toggle('lab-active',view==='lab');document.body.classList.toggle('lesson-preview-active',view==='lesson-intro');$('#lesson-intro-view').hidden=view!=='lesson-intro';if(view==='lesson-intro')renderLessonPreview();renderNav();$('#introduction-view').hidden=view!=='introduction';$('.intro h1').innerHTML=view==='introduction'?'Every project has a <span>story.</span>':'Make sense of <span>Git.</span>';$('.intro>div>p').textContent=view==='introduction'?'Start with a familiar idea. Learn the Git words as you go.':'Follow the buttons. Understand the action. Then try the command.';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view||b.dataset.view==='lab'&&view==='lesson-intro'));$('#lab-view').hidden=view!=='lab';$('#reference-view').hidden=view!=='reference';$('#challenge-view').hidden=view!=='challenge';$('.workspace-tabs').hidden=view!=='lab';$('#tour').hidden=view!=='lab';$('#breadcrumb').textContent=view==='introduction'?'Introduction':view==='lab'?'Learning lab':view==='lesson-intro'?'Lesson overview':view==='reference'?'Command reference':'Practice challenges';if(view==='introduction')renderIntroduction();if(view==='reference')renderReference();if(view==='challenge')renderChallenges();}
const commands=[['git remote add origin <url>','Give an existing remote repository the nickname origin.','Create an empty GitHub repository first, then use its URL. This does not upload files.',2],['git init -b main','Turn a folder into a Git repository; name the first branch main.','Run once when starting a new local project.',0],['git clone <url>','Download a repository and its history.','Creates a local copy with origin configured.',3],['git status','Inspect your branch, staged changes, and unstaged changes.','A useful first step whenever you feel lost.',0],['git diff','See the changes between working files and the staging area.','Use git diff --staged to inspect your next commit.',0],['git add <file>','Stage the file’s current content for the next snapshot.','If you edit it again, stage it again to include that edit.',0],['git commit -m "message"','Record the staged snapshot in your local history.','A commit does not publish anything to GitHub.',0],['git switch -c feature','Create a branch and start working on it.','The new branch initially points to your current commit.',1],['git switch main','Switch your working files and HEAD to main.','Save or stash changes before switching when necessary.',1],['git merge feature','Integrate feature into your current branch.','Can fast-forward, create a merge commit, or stop at conflicts.',1],['git fetch origin','Download history and refresh remote-tracking branches.','Does not integrate changes into your current branch.',2],['git pull --ff-only origin main','Fetch and update your current branch only if it can fast-forward.','Diverged branches require an explicit merge or rebase decision.',2],['git push -u origin feature','Publish feature and set its upstream tracking branch.','Push can be rejected if the remote has incompatible updates.',3],['git log --oneline','Read the commits reachable from your current branch.','Each short ID identifies a saved snapshot.',0],['git revert HEAD','Create a new commit that reverses the latest commit.','Suitable for undoing a mistake in shared history.',5],['git restore <file>','Discard unstaged edits in a tracked file.','Destructive: check git diff first. Not simulated here.',5],['git restore --staged <file>','Remove a file’s changes from the staging area.','Keeps the edits in your working directory.',0],['git stash','Temporarily save local changes for later.','Use git stash pop to reapply them; conflicts can occur.',1],['git reset --soft HEAD~1','Move the branch back one commit, keeping changes staged.','Rewrites the local branch. Avoid changing shared history.',5]];
function escapeHTML(s){return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
function renderReference(){ $('#reference-view').innerHTML='<h2>A command for every moment.</h2><input class="reference-search" id="reference-search" placeholder="Search commands or what you want to do…" aria-label="Search command reference"><div class="reference-grid" id="reference-grid"></div>';filterReference('');$('#reference-search').addEventListener('input',e=>filterReference(e.target.value))}
function filterReference(q){const matches=commands.filter(c=>c.join(' ').toLowerCase().includes(q.toLowerCase()));$('#reference-grid').innerHTML=matches.length?matches.map(c=>`<article class="reference-card"><code>${escapeHTML(c[0])}</code><p>${c[1]}</p><small>${c[2]}</small><br><button data-lesson="${c[3]}">Explore this lesson</button></article>`).join(''):'<p>No matching commands. Try “stage”, “branch”, or “undo”.</p>'}
const quizzes=[{name:'Which recipe version gets saved?',tag:'01 · FUNDAMENTALS',desc:'You edit the recipe again after staging it. Which recipe content will the next commit save?',answers:['The version you staged.','Every edit in the working directory.','The current version on GitHub.'],correct:0,why:'git add captures the content at that moment. Later edits stay unstaged until you add them again.',lesson:0},{name:'Fetch or pull?',tag:'02 · REMOTES',desc:'You edited your own recipe on GitHub and want to inspect that update before changing your computer’s copy. What do you run?',answers:['git pull origin main','git fetch origin','git push origin main'],correct:1,why:'Fetch downloads the remote history and updates origin/main. Your working files and local main stay in place.',lesson:2},{name:'Undo without surprises',tag:'03 · SOLO RECOVERY',desc:'A recipe mistake is already saved on your GitHub repository. How do you undo it while keeping the earlier versions?',answers:['Delete the repository.','git reset --hard HEAD~1 and force push','git revert HEAD'],correct:2,why:'Revert records the inverse change as a new commit. Push the correction to update your online copy while preserving the earlier history.',lesson:5}];
function renderChallenges(){ $('#challenge-view').innerHTML='<h2>Put your mental model to the test.</h2><p class="challenge-header">Three quick scenarios. Make a prediction, get an explanation, then explore it in the lab.</p><div class="challenge-list">'+quizzes.map((q,i)=>`<article class="challenge-card"><span>${q.tag}</span><h3>${q.name}</h3><p>${q.desc}</p><button class="primary-button" data-quiz="${i}">Take the challenge <span>⚑</span></button></article>`).join('')+'</div>'}
function openQuiz(i){const q=quizzes[i];openDialog(`<div class="detail-label">${q.tag}</div><h2>${q.name}</h2><p>${q.desc}</p><div class="quiz-options">${q.answers.map((a,j)=>`<button data-answer="${j}" data-quizid="${i}">${escapeHTML(a)}</button>`).join('')}</div><div class="quiz-result" id="quiz-result" aria-live="polite"></div><button class="quiet-button" data-quizlesson="${q.lesson}">Explore in the lab</button>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-begin-lesson'))beginLesson();if(b.hasAttribute('data-review-lesson')){stopTour();view='lesson-intro';renderView();$('#lesson-preview-title').focus({preventScroll:true})}if(b.dataset.workspacePane)setWorkspacePane(b.dataset.workspacePane);if(b.dataset.guidePane)setGuidePane(b.dataset.guidePane);if(b.dataset.fileTab){state.fileTab=b.dataset.fileTab;renderFileWorkbench()}if(b.dataset.lesson!==undefined)selectLesson(Number(b.dataset.lesson));if(b.dataset.view){stopTour();view=b.dataset.view==='lab'&&!lessonStarted?'lesson-intro':b.dataset.view;renderView()}if(b.dataset.mode){selectLesson(b.dataset.mode==='team'?3:0)}if(b.hasAttribute('data-lesson-action')){stopTour();performAction()}if(b.dataset.command){stopTour();execute(b.dataset.command)}if(b.dataset.resolve)resolveConflict(b.dataset.resolve);if(b.dataset.quiz!==undefined)openQuiz(Number(b.dataset.quiz));if(b.dataset.answer!==undefined){const q=quizzes[Number(b.dataset.quizid)];$('#quiz-result').textContent=(Number(b.dataset.answer)===q.correct?'Exactly. ':'Try again. ')+q.why}if(b.dataset.quizlesson){$('#detail-dialog').close();selectLesson(Number(b.dataset.quizlesson))}});
$('#graph').addEventListener('click',e=>{const n=e.target.closest('[data-commit]');if(n)inspectCommit(n.dataset.commit)});$('#graph').addEventListener('keydown',e=>{const n=e.target.closest('[data-commit]');if(n&&['Enter',' '].includes(e.key)){e.preventDefault();inspectCommit(n.dataset.commit)}});
$('#terminal-form').addEventListener('submit',e=>{e.preventDefault();stopTour();execute($('#command-input').value);$('#command-input').value=''});$('#command-input').addEventListener('keydown',e=>{if(e.key==='ArrowUp'){e.preventDefault();historyIndex=Math.max(0,historyIndex-1);e.target.value=commandHistory[historyIndex]||''}if(e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.min(commandHistory.length,historyIndex+1);e.target.value=commandHistory[historyIndex]||''}});
$('#next-action').addEventListener('click',()=>{stopTour();performAction()});$('#reset').addEventListener('click',()=>{selectLesson(lesson);toast('Lesson reset. Your learning progress is kept.')});$('#tour').addEventListener('click',toggleTour);$('.dialog-close').addEventListener('click',()=>$('#detail-dialog').close());$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#motion-toggle').addEventListener('click',()=>{const paused=document.body.classList.toggle('motion-paused');$('#motion-toggle').setAttribute('aria-label',paused?'Resume decorative motion':'Pause decorative motion');$('#motion-toggle').title=paused?'Resume decorative motion':'Pause decorative motion';toast(paused?'Decorative motion paused':'Decorative motion resumed')});$('#help').addEventListener('click',()=>openDialog('<div class="detail-label">WELCOME TO GIT ORBIT</div><h2>Learn one visible step at a time.</h2><p>New to Git? Open Introduction to try a pancake recipe example. Then follow a lesson with the mint button, play an animated walkthrough, or type commands in the sandbox. Click any commit to see its snapshot and parents.</p><p>This is a simplified learning simulator. It does not execute shell commands or connect to a real GitHub account. Short commit IDs are illustrative. Pull requests and reviews are simulated.</p><p>Progress stays in this browser. Use the motion control to pause decorative animation; your device’s reduced-motion preference is also respected.</p><p>Go deeper with the <a href="https://git-scm.com/book/en/v2" target="_blank" rel="noreferrer">Pro Git book</a> and <a href="https://docs.github.com/en/pull-requests/get-started/about-pull-requests" target="_blank" rel="noreferrer">GitHub pull request guide</a>.</p>'));
document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='l'&&!['INPUT','TEXTAREA'].includes(e.target.tagName)&&!$('#detail-dialog').open){view=lessonStarted?'lab':'lesson-intro';renderView()}});resetLesson();renderView();

